# Negative slots are reserved for successful account/container grants that
# intentionally have no persisted inventory row.  Callers must use the note
# marker rather than treating every negative slot as a capacity failure.
VIRTUAL_GRANT_SLOT = -2


def is_virtual_inventory_grant(note: object) -> bool:
    text = str(note or "")
    return "account_premium=" in text or "account_revive_coin=" in text


def parse_virtual_premium_grant(note: object) -> tuple[int, int] | None:
    match = re.search(
        r"account_premium=item=\d+ type=(\d+) count=\d+ remaining=(\d+)",
        str(note or ""),
    )
    if match is None:
        return None
    premium_type = int(match.group(1)) & 0xFF
    remaining = max(0, int(match.group(2)))
    if premium_type <= 0 or remaining <= 0:
        return None
    return premium_type, remaining


def parse_virtual_premium_grants(note: object) -> tuple[tuple[int, int], ...]:
    values: list[tuple[int, int]] = []
    for match in re.finditer(
        r"account_premium=item=\d+ type=(\d+) count=\d+ remaining=(\d+)",
        str(note or ""),
    ):
        premium_type = int(match.group(1)) & 0xFF
        remaining = max(0, int(match.group(2)))
        if premium_type > 0 and remaining > 0:
            values.append((premium_type, remaining))
    return tuple(values)

