class _UpgradeTransactionReject(Exception):
    def __init__(self, reason: str, detail: dict[str, Any] | None = None) -> None:
        super().__init__(reason)
        self.reason = str(reason)
        self.detail = dict(detail or {})


class _CompoundTransactionReject(Exception):
    """Abort one recipe transaction without committing a partial inventory plan."""

    def __init__(self, reason: str, detail: dict[str, Any] | None = None) -> None:
        super().__init__(reason)
        self.reason = str(reason)
        self.detail = dict(detail or {})


class _AdventureFeatureTransactionReject(Exception):
    """Roll back one dispatch/shop settlement without partial item grants."""

    def __init__(self, reason: str, detail: dict[str, Any] | None = None) -> None:
        super().__init__(reason)
        self.reason = str(reason)
        self.detail = dict(detail or {})


class _DailyGiftTransactionReject(Exception):
    """Roll back one PVF daily-reward sequence without partial delivery."""

    def __init__(self, reason: str, detail: dict[str, Any] | None = None) -> None:
        super().__init__(reason)
        self.reason = str(reason)
        self.detail = dict(detail or {})


